9	/**
10	 * Rewrites the built owner's telephone into E.164 form (see {@link E164Telephone}) in place, so
11	 * later steps save and return it as {@code telephone}. A number that cannot form valid E.164 is
12	 * rejected 400 via {@link MissingOwnerFieldsException}.
13	 */
14	public class NormalizeOwnerTelephone {
15	
16	    public void service(@Val Owner owner) throws MissingOwnerFieldsException {
17	        String e164 = E164Telephone.toE164(owner.getTelephone());
18	        if (e164 == null) {
19	            throw new MissingOwnerFieldsException(List.of("telephone"));
20	        }
21	        owner.setTelephone(e164);
22	    }
23	}
