3	import java.util.List;
4	import java.util.Locale;
5	import java.util.regex.Pattern;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
10	
11	/**
12	 * Email is optional: a missing (null/blank) value is left untouched. When present it must be a
13	 * syntactically valid address, otherwise the request is rejected 400 via
14	 * {@link MissingOwnerFieldsException}. A valid value is lower-cased in place, so later steps save
15	 * and return it as {@code email}.
16	 */
17	public class NormalizeOwnerEmail {
18	
19	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
20	
21	    public void service(@Val Owner owner) throws MissingOwnerFieldsException {
22	        String email = owner.getEmail();
23	        if (email == null || email.isBlank()) {
24	            return;
25	        }
26	        if (!EMAIL.matcher(email).matches()) {
27	            throw new MissingOwnerFieldsException(List.of("email"));
28	        }
29	        owner.setEmail(email.toLowerCase(Locale.ROOT));
30	    }
31	}
