9	/**
10	 * Assigns the owner's {@code customerCode} formatted {@code <LAST3>-<NNNN>}: LAST3 is the
11	 * upper-cased first three letters of the last name and NNNN is a global 4-digit zero-padded
12	 * sequence equal to one more than the current number of owners. Runs before {@link SaveOwner},
13	 * so this owner is not yet counted (e.g. 'SMI-0007').
14	 */
15	public class AssignOwnerCustomerCode {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        String lastName = owner.getLastName();
19	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
20	        int sequence = ownerRepository.findAll().size() + 1;
21	        owner.setCustomerCode(String.format("%s-%04d", last3, sequence));
22	    }
23	}
