3	/**
4	 * Converts a raw telephone into E.164 form: keeps a leading '+' and country code when present,
5	 * otherwise assumes country code '+61' and drops a single leading '0' from the national digits.
6	 * Spaces, dashes and brackets are stripped. Returns {@code null} when the result would not have
7	 * 8 to 15 digits after the '+'.
8	 */
9	final class E164Telephone {
10	
11	    private E164Telephone() {
12	    }
13	
14	    static String toE164(String raw) {
15	        if (raw == null) {
16	            return null;
17	        }
18	        boolean international = raw.trim().startsWith("+");
19	        String digits = raw.replaceAll("\\D", "");
20	        if (!international) {
21	            if (digits.startsWith("0")) {
22	                digits = digits.substring(1);
23	            }
24	            digits = "61" + digits;
25	        }
26	        if (digits.length() < 8 || digits.length() > 15) {
27	            return null;
28	        }
29	        return "+" + digits;
30	    }
31	}
